children.script:
var hints = {
  dbml: 'Paste into this <a href="https://dbdiagram.io/d" target="_blank">online visualization tool</a>.',
  mermaid: 'Paste into a ```mermaid block of a Markdown file, e.g. in VS Code.'
};
function fmt(){
  return document.getElementById('format').value
}
function show(){
  document.getElementById('pre').textContent = context[fmt()]
  document.getElementById('hint').innerHTML = hints[fmt()] + ' You can restrict the output to a database by editing the expression of this widget in the layout editor, e.g. $erDiagram(\'northwind\', \'mermaid\').'
}
function copy(){
  navigator.clipboard.writeText(context[fmt()])
}
show()
